Here is the commit message:
sfc: correctly initialise filter rwsem for farch

Fixes: fc7a6c287ff3 ("sfc: use a semaphore to lock farch filters too")
Suggested-by: Joseph Korty <joe.korty@concurrent-rt.com>
Signed-off-by: Bert Kenward <bkenward@solarflare.com>
Signed-off-by: David S. Miller <davem@davemloft.net>

Here is the root cause:
The bug was caused by the lack of proper initialization of the read-write semaphore (`rwsem`) used to manage concurrent access to the filter state in the `efx_farch_filter_table_probe` function. Without initializing the semaphore, any subsequent operations that rely on it for locking could lead to undefined behavior, race conditions, or access violations when multiple threads attempt to modify the filter state simultaneously.

Here is the patch:

 int efx_farch_filter_table_probe(struct efx_nic *efx)
 {
 	struct efx_farch_filter_state *state;
 	struct efx_farch_filter_table *table;
 	unsigned table_id;

 	state = kzalloc(sizeof(struct efx_farch_filter_state), GFP_KERNEL);
 	if (!state)
 		return -ENOMEM;
 	efx->filter_state = state;
+	init_rwsem(&state->lock);

 	table = &state->table[EFX_FARCH_FILTER_TABLE_RX_IP];
 	table->id = EFX_FARCH_FILTER_TABLE_RX_IP;
 	table->offset = FR_BZ_RX_FILTER_TBL0;
 	table->size = FR_BZ_RX_FILTER_TBL0_ROWS;
 	table->step = FR_BZ_RX_FILTER_TBL0_STEP;

 	table = &state->table[EFX_FARCH_FILTER_TABLE_RX_MAC];
 	table->id = EFX_FARCH_FILTER_TABLE_RX_MAC;
 	table->offset = FR_CZ_RX_MAC_FILTER_TBL0;
 	table->size = FR_CZ_RX_MAC_FILTER_TBL0_ROWS;
 	table->step = FR_CZ_RX_MAC_FILTER_TBL0_STEP;

 	table = &state->table[EFX_FARCH_FILTER_TABLE_RX_DEF];
 	table->id = EFX_FARCH_FILTER_TABLE_RX_DEF;
 	table->size = EFX_FARCH_FILTER_SIZE_RX_DEF;

 	table = &state->table[EFX_FARCH_FILTER_TABLE_TX_MAC];
 	table->id = EFX_FARCH_FILTER_TABLE_TX_MAC;
 	table->offset = FR_CZ_TX_MAC_FILTER_TBL0;
 	table->size = FR_CZ_TX_MAC_FILTER_TBL0_ROWS;
 	table->step = FR_CZ_TX_MAC_FILTER_TBL0_STEP;

 	for (table_id = 0; table_id < EFX_FARCH_FILTER_TABLE_COUNT; table_id++) {
 		table = &state->table[table_id];
 		if (table->size == 0)
 			continue;
 		table->used_bitmap = kcalloc(BITS_TO_LONGS(table->size),
 					     sizeof(unsigned long),
 					     GFP_KERNEL);
 		if (!table->used_bitmap)
 			goto fail;
 		table->spec = vzalloc(array_size(sizeof(*table->spec),
 						 table->size));
 		if (!table->spec)
 			goto fail;
 	}

 	table = &state->table[EFX_FARCH_FILTER_TABLE_RX_DEF];
 	if (table->size) {
 		/* RX default filters must always exist */
 		struct efx_farch_filter_spec *spec;
 		unsigned i;

 		for (i = 0; i < EFX_FARCH_FILTER_SIZE_RX_DEF; i++) {
 			spec = &table->spec[i];
 			spec->type = EFX_FARCH_FILTER_UC_DEF + i;
 			efx_farch_filter_init_rx_auto(efx, spec);
 			__set_bit(i, table->used_bitmap);
 		}
 	}

 	efx_farch_filter_push_rx_config(efx);

 	return 0;

 fail:
 	efx_farch_filter_table_remove(efx);
 	return -ENOMEM;
 }



